#!/usr/bin/env python3
"""
This program uses a recursive backtracking algorithm to solve the Zebra puzzle.
It builds an assignment for 6 houses with the attributes:
  Name, Food, Height, Drink, Pet, PhoneModel
and checks all given constraints.
When a complete solution is found, it prints the solution in the required JSON format.
"""

import json
import copy

# The lists of possible attribute values.
NAMES = ["Arnold", "Bob", "Peter", "Alice", "Carol", "Eric"]
FOODS = ["stew", "grilled cheese", "stir fry", "soup", "pizza", "spaghetti"]
HEIGHTS = ["tall", "average", "super tall", "very short", "very tall", "short"]
DRINKS = ["root beer", "boba tea", "coffee", "water", "tea", "milk"]
PETS = ["hamster", "fish", "cat", "dog", "bird", "rabbit"]
PHONES = ["samsung galaxy s21", "xiaomi mi 11", "google pixel 6", "iphone 13", "huawei p50", "oneplus 9"]

# For ease of checking, we make a list of category keys.
CATEGORIES = ["Name", "Food", "Height", "Drink", "Pet", "Phone"]

def full_check(houses):
    """Check all constraints on a complete assignment (6 houses)."""
    # Houses are indexed 0..5 corresponding to House1..House6.
    # Helper: get index (if exists) for a house with a given attribute value (unique in complete solution).
    def find_index(cat, val):
        for idx, house in enumerate(houses):
            if house[cat] == val:
                return idx
        return None

    # 1. House3 (index 2) Phone must be "iphone 13"
    if houses[2]["Phone"] != "iphone 13":
        return False
    # 2. House2 (index 1) Food must be "soup"
    if houses[1]["Food"] != "soup":
        return False

    for i, house in enumerate(houses):
        name = house["Name"]
        food = house["Food"]
        height = house["Height"]
        drink = house["Drink"]
        pet = house["Pet"]
        phone = house["Phone"]

        # Local constraints:
        # 9. Arnold uses OnePlus 9.
        if name == "Arnold" and phone != "oneplus 9":
            return False
        # 15. Carol uses samsung galaxy s21.
        if name == "Carol" and phone != "samsung galaxy s21":
            return False
        # 17. Arnold is very tall.
        if name == "Arnold" and height != "very tall":
            return False
        # 2. Bob is tall.
        if name == "Bob" and height != "tall":
            return False
        # 7. The person who loves grilled cheese is tall.
        if food == "grilled cheese" and height != "tall":
            return False
        # 13. Alice owns the fish.
        if name == "Alice" and pet != "fish":
            return False
        # Also, clue 12: The person who is super tall is the one with fish.
        if pet == "fish" and height != "super tall":
            return False
        # 18. Google Pixel 6 user loves spaghetti.
        if phone == "google pixel 6" and food != "spaghetti":
            return False
        # 23. The person who loves spaghetti is very short.
        if food == "spaghetti" and height != "very short":
            return False
        # 8. Xiaomi mi 11 user drinks coffee.
        if phone == "xiaomi mi 11" and drink != "coffee":
            return False
        # 6. Stir fry lover drinks milk.
        if food == "stir fry" and drink != "milk":
            return False
        # 26. Dog owner drinks milk.
        if pet == "dog" and drink != "milk":
            return False
        # 16. Pizza lover is short.
        if food == "pizza" and height != "short":
            return False

        # Also, if a house has stir fry then it must have dog (by clues 6 and 26 combined).
        if food == "stir fry":
            if pet != "dog":
                return False

    # 4. The root beer lover is directly left of the person who uses Xiaomi Mi 11.
    for i in range(5):
        if houses[i]["Drink"] == "root beer":
            if houses[i+1]["Phone"] != "xiaomi mi 11":
                return False

    # 5. The person who uses Huawei P50 is directly left of the person who loves grilled cheese.
    for i in range(5):
        if houses[i]["Phone"] == "huawei p50":
            if houses[i+1]["Food"] != "grilled cheese":
                return False

    # 14. The tea drinker is directly left of the person who is a pizza lover.
    for i in range(5):
        if houses[i]["Drink"] == "tea":
            if houses[i+1]["Food"] != "pizza":
                return False

    # 19. The boba tea drinker is somewhere to the right of the person who loves soup.
    idx_soup = find_index("Food", "soup")
    idx_boba = find_index("Drink", "boba tea")
    if idx_soup is None or idx_boba is None or idx_soup >= idx_boba:
        return False

    # 11. The person with a pet hamster is somewhere to the right of the person who uses Google Pixel 6.
    idx_pixel = find_index("Phone", "google pixel 6")
    idx_hamster = find_index("Pet", "hamster")
    if idx_pixel is None or idx_hamster is None or idx_pixel >= idx_hamster:
        return False

    # 20. The pet rabbit is not in the fifth house (index 4) and pet hamster is not in the fifth house.
    if houses[4]["Pet"] in ["rabbit", "hamster"]:
        return False

    # 21. The very tall person is not in the second house (index 1).
    if houses[1]["Height"] == "very tall":
        return False

    # 22. The person who is super tall (Alice) is somewhere to the left of Peter.
    idx_alice = None
    idx_peter = None
    for i, h in enumerate(houses):
        if h["Name"] == "Alice":
            idx_alice = i
        if h["Name"] == "Peter":
            idx_peter = i
    if idx_alice is None or idx_peter is None or idx_alice >= idx_peter:
        return False

    # 24. The person with a pet bird is somewhere to the left of the person who loves spaghetti.
    idx_bird = find_index("Pet", "bird")
    idx_spag = find_index("Food", "spaghetti")
    if idx_bird is None or idx_spag is None or idx_bird >= idx_spag:
        return False

    # 25. The person with the fish (Alice) is directly left of Eric.
    for i in range(5):
        if houses[i]["Name"] == "Alice":
            if houses[i+1]["Name"] != "Eric":
                return False

    return True

def partial_check(houses, filled):
    """
    Check constraints that involve houses indices [0, filled-1].
    We check constraints that can be evaluated when the houses in question are assigned.
    'filled' is the number of houses already assigned.
    """
    # For fixed-position constraints:
    if filled > 1:
        # House2 (index 1) Food must be "soup"
        if houses[1]["Food"] != "soup":
            return False
    if filled > 2:
        # House3 (index 2) Phone must be "iphone 13"
        if houses[2]["Phone"] != "iphone 13":
            return False

    # Check each assigned house's local constraints:
    for i in range(filled):
        house = houses[i]
        name = house["Name"]
        food = house["Food"]
        height = house["Height"]
        drink = house["Drink"]
        pet = house["Pet"]
        phone = house["Phone"]

        if name == "Arnold":
            if phone is not None and phone != "oneplus 9":
                return False
            if height is not None and height != "very tall":
                return False
        if name == "Carol":
            if phone is not None and phone != "samsung galaxy s21":
                return False
        if name == "Bob":
            if height is not None and height != "tall":
                return False
        if name == "Alice":
            if pet is not None and pet != "fish":
                return False
            if height is not None and height != "super tall":
                return False
        if food == "grilled cheese":
            if height is not None and height != "tall":
                return False
        if phone == "google pixel 6":
            if food is not None and food != "spaghetti":
                return False
        if food == "spaghetti":
            if height is not None and height != "very short":
                return False
        if phone == "xiaomi mi 11":
            if drink is not None and drink != "coffee":
                return False
        if food == "stir fry":
            if drink is not None and drink != "milk":
                return False
            if pet is not None and pet != "dog":
                return False
        if pet == "dog":
            if drink is not None and drink != "milk":
                return False
        if food == "pizza":
            if height is not None and height != "short":
                return False

    # Check adjacent constraints that can be checked when both houses are filled:
    for i in range(filled - 1):
        # Clue 4: If house i drink is "root beer", then house i+1 Phone must be "xiaomi mi 11"
        if houses[i]["Drink"] == "root beer":
            if houses[i+1]["Phone"] is not None and houses[i+1]["Phone"] != "xiaomi mi 11":
                return False
        # Clue 5: If house i Phone is "huawei p50", then house i+1 Food must be "grilled cheese"
        if houses[i]["Phone"] == "huawei p50":
            if houses[i+1]["Food"] is not None and houses[i+1]["Food"] != "grilled cheese":
                return False
        # Clue 14: If house i Drink is "tea", then house i+1 Food must be "pizza"
        if houses[i]["Drink"] == "tea":
            if houses[i+1]["Food"] is not None and houses[i+1]["Food"] != "pizza":
                return False

    # Check ordering constraints if the relevant houses are assigned:
    def find_assigned_index(cat, val):
        for idx in range(filled):
            if houses[idx][cat] == val:
                return idx
        return None

    idx_soup = find_assigned_index("Food", "soup")
    idx_boba = find_assigned_index("Drink", "boba tea")
    if idx_soup is not None and idx_boba is not None:
        if idx_soup >= idx_boba:
            return False

    idx_pixel = find_assigned_index("Phone", "google pixel 6")
    idx_hamster = find_assigned_index("Pet", "hamster")
    if idx_pixel is not None and idx_hamster is not None:
        if idx_pixel >= idx_hamster:
            return False

    # Clue 21: House2 (index 1) is not very tall.
    if filled > 1:
        if houses[1]["Height"] == "very tall":
            return False

    # Clue 22: Alice must be to the left of Peter.
    def find_name(name):
        for idx in range(filled):
            if houses[idx]["Name"] == name:
                return idx
        return None
    idx_alice = find_name("Alice")
    idx_peter = find_name("Peter")
    if idx_alice is not None and idx_peter is not None:
        if idx_alice >= idx_peter:
            return False

    # Clue 24: Bird is to the left of spaghetti.
    idx_bird = find_assigned_index("Pet", "bird")
    idx_spag = find_assigned_index("Food", "spaghetti")
    if idx_bird is not None and idx_spag is not None:
        if idx_bird >= idx_spag:
            return False

    # Clue 25: The person with fish (Alice) is directly left of Eric.
    for i in range(filled - 1):
        if houses[i]["Name"] == "Alice":
            if houses[i+1]["Name"] is not None and houses[i+1]["Name"] != "Eric":
                return False

    # Clue 10 & 20: For house 5 (index 4) if assigned, Pet must not be "rabbit" or "hamster".
    if filled > 4:
        if houses[4]["Pet"] in ["rabbit", "hamster"]:
            return False

    return True

def backtrack(i, houses, avail):
    """Recursive backtracking assignment for house index i (0-indexed).
       houses: list of length 6 of assignments (each a dict for the house).
       avail: dictionary mapping category -> remaining possible values.
    """
    if i == 6:
        # Complete assignment; check full constraints.
        if full_check(houses):
            return houses
        else:
            return None

    # For current house, iterate over all possible combinations (Cartesian product) of available values.
    for name in avail["Name"]:
        for food in avail["Food"]:
            # If we are placing house2 (i==1), food must be "soup"
            if i == 1 and food != "soup":
                continue
            for height in avail["Height"]:
                # If house2 (i==1) cannot be "very tall" per clue 21.
                if i == 1 and height == "very tall":
                    continue
                for drink in avail["Drink"]:
                    for pet in avail["Pet"]:
                        for phone in avail["Phone"]:
                            # For house3 (i==2), phone must be "iphone 13".
                            if i == 2 and phone != "iphone 13":
                                continue
                            # Build current house dictionary.
                            house = {
                                "Name": name,
                                "Food": food,
                                "Height": height,
                                "Drink": drink,
                                "Pet": pet,
                                "Phone": phone
                            }
                            houses[i] = house
                            # Create new copy of available values for next recursion.
                            new_avail = {}
                            for cat in avail:
                                new_avail[cat] = avail[cat].copy()
                            new_avail["Name"].remove(name)
                            new_avail["Food"].remove(food)
                            new_avail["Height"].remove(height)
                            new_avail["Drink"].remove(drink)
                            new_avail["Pet"].remove(pet)
                            new_avail["Phone"].remove(phone)

                            # Check partial constraints for houses up to index i.
                            if not partial_check(houses, i+1):
                                continue

                            result = backtrack(i+1, houses, new_avail)
                            if result is not None:
                                return result
    houses[i] = None
    return None

def solve_puzzle():
    # Initialize houses as a list of 6 elements.
    houses = [None] * 6
    # Make available sets (lists) for each category.
    avail = {
        "Name": NAMES.copy(),
        "Food": FOODS.copy(),
        "Height": HEIGHTS.copy(),
        "Drink": DRINKS.copy(),
        "Pet": PETS.copy(),
        "Phone": PHONES.copy()
    }
    solution = backtrack(0, houses, avail)
    return solution

def main():
    sol = solve_puzzle()
    # Format the solution as required.
    # We want header: ["House", "Name", "Food", "Height", "Drink", "Pet", "PhoneModel"]
    # And rows: list of rows for house numbers 1 to 6.
    if sol is None:
        result = {"solution": {"header": ["House", "Name", "Food", "Height", "Drink", "Pet", "PhoneModel"], "rows": []}}
    else:
        rows = []
        for i, house in enumerate(sol):
            row = [
                str(i+1),
                house["Name"],
                house["Food"],
                house["Height"],
                house["Drink"],
                house["Pet"],
                house["Phone"]
            ]
            rows.append(row)
        result = {"solution": {"header": ["House", "Name", "Food", "Height", "Drink", "Pet", "PhoneModel"], "rows": rows}}
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
